SELECT GameDetailsPeriodsQuery.Period, GameDetailsPeriodsQuery.[GameID]
FROM GameDetailsPeriodsQuery
WHERE (((GameDetailsPeriodsQuery.[GameID])=Forms!GameStatsForm!Combo2));

