FROM GameDetailsQuery
WHERE (((GameDetailsQuery.TimeOfSeason)>1) And ((GameDetailsQuery.TimeOfSeason2)<>"jv") And ((GameDetailsQuery.SeasonID)=Forms!NavigationForm!Season));

